/**
 * The names of the theme's colour tokens as a TypeScript type, so the
 * library's `token()` calls are checked against the theme it ships whatever
 * theme NSH typed `token()` with.
 */
import { buildAppTheme } from '../theme/build.ts';

export function themeColorNames(): string[] {
  return Object.keys(buildAppTheme().cssVars.light).sort();
}

export function renderTokenModule(): string {
  const names = themeColorNames();
  return [
    '// Generated by sdk-internal/ui/scripts/generate.ts from theme/build.ts.',
    '// Do not edit.',
    '',
    '/** A colour token of the App theme. */',
    'export type ThemeColor =',
    ...names.map(
      (name, index) => `  | '${name}'${index === names.length - 1 ? ';' : ''}`,
    ),
    '',
  ].join('\n');
}
